(() => {
  'use strict';
  const engine = globalThis.AlarmPuzzleEngine;
  const scenes = globalThis.AlarmPuzzleScenes;

  function attach(document, view) {
    const get = (id) => document.getElementById(id);
    const pump = get('pump');
    const status = get('status');
    const restart = get('restart');
    let scene = scenes.balloons;
    let state = engine.createState(scene.itemIds.length);
    let drag = null;

    function render() {
      pump.style.setProperty('--pull', `${state.pull * scene.distance}px`);
      pump.classList.toggle('dragging', drag !== null);
      pump.disabled = state.phase === 'done';
      pump.setAttribute('aria-label', `${scene.tool}, ${state.cleared}개 수거`);
      get('meter-fill').style.width = `${state.pull * 100}%`;
      get('counter').textContent = `수거 ${state.cleared} / ${state.total}`;
      get('basket-count').textContent = Array.from({ length: state.total }, (_, i) => i < state.cleared ? '●' : '○').join(' ');
      get('finish').hidden = state.phase !== 'done';
      get('pull-hint').hidden = state.phase === 'done';
      scene.itemIds.forEach((id, i) => {
        const item = get(id);
        const remaining = engine.pressure(state, i);
        item.classList.toggle('collected', i < state.cleared);
        item.classList.toggle('active', i === state.cleared);
        item.style.setProperty('--scale', String(0.57 + 0.43 * remaining));
        item.style.setProperty('--feed', `${(1 - remaining) * 100}px`);
        item.style.setProperty('--paper-scale', String(Math.max(0.2, remaining)));
        item.setAttribute('aria-hidden', String(i < state.cleared));
      });
    }

    function showScene() {
      get('workshop').setAttribute('data-scene', scene.id);
      for (const option of Object.values(scenes)) {
        get(`${option.id}-panel`).hidden = option.id !== scene.id;
        get(`choose-${option.id}`).setAttribute('aria-pressed', String(option.id === scene.id));
      }
      get('scene-title').textContent = scene.title;
      get('scene-accent').textContent = scene.accent;
      get('scene-intro').textContent = scene.intro;
      get('play-scene').setAttribute('aria-label', `${scene.noun} 광고와 ${scene.label}`);
      get('pull-hint').textContent = scene.hint;
      get('controls-help').textContent = scene.help;
      get('track-direction').textContent = scene.direction;
      get('tool-stamp').textContent = scene.stamp;
      get('tool-label').textContent = scene.label;
      get('finish-copy').textContent = scene.finish;
      pump.textContent = scene.handle;
    }

    function finishPull() {
      const previous = state;
      state = engine.release(state);
      if (state.phase === 'done') {
        status.textContent = '모든 알림 수거 완료. 다시 시작할 수 있어요.';
      } else if (state.cleared > previous.cleared) {
        status.textContent = `${scene.noun} 하나 수거! ${state.total - state.cleared}개 남았어요.`;
      } else if (state.strokes > previous.strokes) {
        status.textContent = scene.partial;
      } else {
        status.textContent = scene.short;
      }
      render();
      if (state.phase === 'done') restart.focus();
    }

    function stopDrag(cancelled) {
      if (!drag) return;
      const pointerId = drag.id;
      // Clear ownership before releasing capture: lostpointercapture may re-enter.
      drag = null;
      if (pump.hasPointerCapture(pointerId)) pump.releasePointerCapture(pointerId);
      if (cancelled) {
        state = engine.cancel(state);
        status.textContent = '조작을 멈췄어요. 다시 손잡이를 잡아주세요.';
        render();
      } else finishPull();
    }

    function outsideView(event) {
      return event.clientX < 0 || event.clientY < 0 ||
        event.clientX >= view.innerWidth || event.clientY >= view.innerHeight;
    }

    pump.addEventListener('pointerdown', (event) => {
      if (state.phase === 'done' || drag || event.button !== 0) return;
      event.preventDefault();
      drag = { id: event.pointerId, start: event[scene.axis] };
      pump.setPointerCapture(event.pointerId);
      status.textContent = scene.drag;
      render();
    });
    pump.addEventListener('pointermove', (event) => {
      if (!drag || event.pointerId !== drag.id) return;
      if (outsideView(event)) {
        stopDrag(true);
        return;
      }
      state = engine.pull(state, (event[scene.axis] - drag.start) / scene.distance);
      status.textContent = state.pull >= engine.THRESHOLD ? '좋아요, 이제 놓아주세요!' : scene.preview;
      render();
    });
    pump.addEventListener('pointerup', (event) => {
      if (drag && event.pointerId === drag.id) stopDrag(outsideView(event));
    });
    for (const name of ['pointercancel', 'lostpointercapture']) {
      pump.addEventListener(name, (event) => {
        if (drag && event.pointerId === drag.id) stopDrag(true);
      });
    }
    view.addEventListener('blur', () => stopDrag(true));
    view.addEventListener('pagehide', () => stopDrag(true));
    view.addEventListener('pointerout', (event) => {
      if (drag && event.pointerId === drag.id && event.relatedTarget === null) stopDrag(true);
    });
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) stopDrag(true);
    });
    pump.addEventListener('keydown', (event) => {
      if (![scene.key, ' ', 'Enter'].includes(event.key)) return;
      event.preventDefault();
      if (event.repeat || drag || state.phase === 'done') return;
      state = engine.pull(state, 1);
      finishPull();
    });
    function reset(nextScene) {
      stopDrag(true);
      scene = nextScene;
      state = engine.createState(scene.itemIds.length);
      showScene();
      status.textContent = scene.start;
      render();
      pump.focus();
    }
    restart.addEventListener('click', () => reset(scene));
    for (const option of Object.values(scenes)) {
      get(`choose-${option.id}`).addEventListener('click', () => {
        if (option.id !== scene.id) reset(option);
      });
    }
    showScene();
    status.textContent = scene.start;
    render();
    return { getState: () => ({ ...state }), getScene: () => scene.id };
  }

  globalThis.AlarmPuzzleApp = Object.freeze({ attach });
  if (typeof document !== 'undefined') attach(document, globalThis);
})();

