/* Classic script so index.html also works directly from disk, without a server. */
(() => {
  'use strict';
  const THRESHOLD = 0.85;
  const BALLOONS = 3;
  const STROKES_PER_BALLOON = 2;

  function createState(total = BALLOONS) {
    if (!Number.isInteger(total) || total < 1) throw new RangeError('Item count must be a positive integer');
    return { total, strokes: 0, pull: 0, cleared: 0, phase: 'playing' };
  }

  function pull(state, distance) {
    if (state.phase !== 'playing') return state;
    return { ...state, pull: Number.isFinite(distance) ? Math.max(0, Math.min(1, distance)) : 0 };
  }

  function cancel(state) {
    return { ...state, pull: 0 };
  }

  function release(state) {
    if (state.phase !== 'playing' || state.pull < THRESHOLD) return cancel(state);
    const strokes = state.strokes + 1;
    const cleared = Math.floor(strokes / STROKES_PER_BALLOON);
    return { ...state, strokes, cleared, pull: 0, phase: cleared === state.total ? 'done' : 'playing' };
  }

  function pressure(state, index) {
    if (index < state.cleared) return 0;
    if (index > state.cleared) return 1;
    return Math.max(0, 1 - (state.strokes % STROKES_PER_BALLOON + state.pull) / STROKES_PER_BALLOON);
  }

  globalThis.AlarmPuzzleEngine = Object.freeze({ createState, pull, cancel, release, pressure, THRESHOLD, BALLOONS });
})();

