import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import vm from 'node:vm';

const source = (path) => readFileSync(new URL(`../${path}`, import.meta.url), 'utf8');
const context = vm.createContext({});
vm.runInContext(source('src/scenes.js'), context);
vm.runInContext(source('src/puzzle.js'), context);
vm.runInContext(source('src/app.js'), context);
const engine = context.AlarmPuzzleEngine;
const plain = (value) => JSON.parse(JSON.stringify(value));
const stroke = (state) => engine.release(engine.pull(state, 1));

test('new puzzle begins with three full balloons and zero collected', () => {
  const state = engine.createState();
  assert.deepEqual(plain(state), { total: 3, strokes: 0, cleared: 0, pull: 0, phase: 'playing' });
  assert.deepEqual([0, 1, 2].map((i) => engine.pressure(state, i)), [1, 1, 1]);
});

test('partial pulling previews deflation without counting a stroke', () => {
  const initial = engine.createState();
  const preview = engine.pull(initial, 0.5);
  assert.equal(engine.pressure(preview, 0), 0.75);
  assert.equal(engine.pressure(preview, 1), 1);
  assert.equal(preview.strokes, 0);
  assert.equal(initial.pull, 0);
});

test('tap, upward pull and short pull cannot clear advertisements', () => {
  for (const distance of [0, -1, 0.3, engine.THRESHOLD - 0.01]) {
    assert.deepEqual(plain(engine.release(engine.pull(engine.createState(), distance))), plain(engine.createState()));
  }
});

test('threshold completes one stroke; second stroke collects the first balloon', () => {
  const first = engine.release(engine.pull(engine.createState(), engine.THRESHOLD));
  assert.equal(first.strokes, 1);
  assert.equal(first.cleared, 0);
  assert.equal(engine.pressure(first, 0), 0.5);
  const second = stroke(first);
  assert.equal(second.cleared, 1);
  assert.equal(engine.pressure(second, 0), 0);
  assert.equal(engine.pressure(second, 1), 1);
});

test('cancel discards even a full preview, preserving already completed work', () => {
  const state = stroke(engine.createState());
