class Element {
  constructor() {
    this.handlers = {};
    this.style = { setProperty(name, value) { this[name] = value; } };
    this.classes = new Set();
    this.classList = { toggle: (name, value) => value ? this.classes.add(name) : this.classes.delete(name) };
    this.attributes = {};
    this.captures = new Set();
    this.hidden = false;
    this.disabled = false;
    this.textContent = '';
    this.focused = false;
  }
  addEventListener(name, handler) { (this.handlers[name] ??= []).push(handler); }
  setAttribute(name, value) { this.attributes[name] = value; }
  setPointerCapture(id) { this.captures.add(id); }
  hasPointerCapture(id) { return this.captures.has(id); }
  releasePointerCapture(id) { this.captures.delete(id); this.emit('lostpointercapture', { pointerId: id }); }
  focus() { this.focused = true; }
  emit(name, fields = {}) {
    const event = { pointerId: 1, clientX: 100, clientY: 100, button: 0, repeat: false, preventDefault() {}, ...fields };
    for (const handler of this.handlers[name] ?? []) handler(event);
  }
}

function fixture() {
  const elements = Object.fromEntries(['pump', 'status', 'restart', 'meter-fill', 'counter', 'basket-count', 'finish', 'pull-hint', 'balloon-0', 'balloon-1', 'balloon-2', 'coupon-0', 'coupon-1', 'workshop', 'balloons-panel', 'coupons-panel', 'choose-balloons', 'choose-coupons', 'scene-title', 'scene-accent', 'scene-intro', 'play-scene', 'controls-help', 'track-direction', 'tool-stamp', 'tool-label', 'finish-copy'].map((id) => [id, new Element()]));
  const view = new Element();
  view.innerWidth = 400;
  view.innerHeight = 800;
  const document = new Element();
  document.getElementById = (id) => elements[id];
  const app = context.AlarmPuzzleApp.attach(document, view);
  const pull = (endY = 182, pointerId = 1) => {
    elements.pump.emit('pointerdown', { pointerId });
    elements.pump.emit('pointermove', { clientY: endY, pointerId });
    elements.pump.emit('pointerup', { clientY: endY, pointerId });
  };
  return { elements, document, view, app, pull };
}

