test('leaving any viewport edge cancels the current pull and ignores the late release', () => {
  for (const outside of [{ clientX: -1 }, { clientX: 400 }, { clientY: -1 }, { clientY: 800 }]) {
    const { elements, app, pull } = fixture();
    pull();
    elements.pump.emit('pointerdown');
    elements.pump.emit('pointermove', { clientY: 182 });
    elements.pump.emit('pointermove', { clientY: 182, ...outside });
    elements.pump.emit('pointerup', { clientY: 182 });
    assert.equal(app.getState().strokes, 1, JSON.stringify(outside));
    assert.equal(app.getState().pull, 0);
    assert.equal(elements.pump.hasPointerCapture(1), false);
    assert.equal(elements.pump.classes.has('dragging'), false);
    pull();
    assert.equal(app.getState().cleared, 1);
  }
});

