for (const reason of ['hidden', 'pagehide']) {
  test(`${reason} cancels a full pull and allows a fresh pull after returning`, () => {
    const { elements, document, view, app, pull } = fixture();
    pull();
    elements.pump.emit('pointerdown');
    elements.pump.emit('pointermove', { clientY: 182 });
    document.emit('visibilitychange');
    assert.equal(app.getState().pull, 1, 'visible notification must not cancel');
    if (reason === 'hidden') {
      document.hidden = true;
      document.emit('visibilitychange');
      document.hidden = false;
      document.emit('visibilitychange');
    } else view.emit('pagehide');
    elements.pump.emit('pointerup', { clientY: 182 });
    assert.equal(app.getState().strokes, 1);
    assert.equal(elements['meter-fill'].style.width, '0%');
    pull();
    assert.equal(app.getState().cleared, 1);
  });
}

test('restart handler during a pull clears progress and ignores obsolete pointer events', () => {
  const { elements, app, pull } = fixture();
  pull();
  elements.pump.emit('pointerdown');
  elements.pump.emit('pointermove', { clientY: 182 });
  // Reset during an owned gesture must make late events harmless.
  elements.restart.emit('click');
  elements.pump.emit('pointermove', { clientY: 300 });
  elements.pump.emit('pointerup', { clientY: 300 });
  elements.pump.emit('lostpointercapture');
  assert.deepEqual(plain(app.getState()), plain(engine.createState()));
  assert.equal(elements.pump.hasPointerCapture(1), false);
  assert.equal(elements['meter-fill'].style.width, '0%');
  assert.equal(elements.pump.classes.has('dragging'), false);
  pull();
  assert.equal(app.getState().strokes, 1);
});

test('two complete plays with cancellation and repeated restart have no carried-over state', () => {
  const { elements, app, pull } = fixture();
  for (let round = 0; round < 2; round++) {
    for (let i = 0; i < 3; i++) pull();
    elements.pump.emit('pointerdown');
    elements.pump.emit('pointermove', { clientY: 182 });
    elements.pump.emit('pointercancel');
    elements.pump.emit('pointerup', { clientY: 182 });
    for (let i = 0; i < 3; i++) pull();
    assert.equal(app.getState().strokes, 6);
    assert.equal(app.getState().phase, 'done');
    assert.equal(elements.counter.textContent, '수거 3 / 3');
    assert.equal(elements.finish.hidden, false);
    elements.restart.emit('click');
    elements.restart.emit('click');
    assert.deepEqual(plain(app.getState()), plain(engine.createState()));
    assert.equal(elements.counter.textContent, '수거 0 / 3');
    assert.equal(elements['basket-count'].textContent, '○ ○ ○');
    assert.equal(elements.finish.hidden, true);
    assert.equal(elements['pull-hint'].hidden, false);
    for (let i = 0; i < 3; i++) {
      assert.equal(elements[`balloon-${i}`].classes.has('collected'), false);
      assert.equal(elements[`balloon-${i}`].style['--scale'], '1');
      assert.equal(elements[`balloon-${i}`].attributes['aria-hidden'], 'false');
    }
  }
});

function slide(elements, endX = 204) {
  elements.pump.emit('pointerdown');
  elements.pump.emit('pointermove', { clientX: endX });
  elements.pump.emit('pointerup', { clientX: endX });
}

