test('coupon cancellation and page hiding preserve completed slides only', () => {
  const { elements, view, document, app } = fixture();
  elements['choose-coupons'].emit('click');
  slide(elements);
  for (const reason of ['pointercancel', 'outside', 'blur', 'hidden']) {
    elements.pump.emit('pointerdown');
    elements.pump.emit('pointermove', { clientX: 204 });
    if (reason === 'outside') elements.pump.emit('pointermove', { clientX: 400 });
    else if (reason === 'blur') view.emit('blur');
    else if (reason === 'hidden') { document.hidden = true; document.emit('visibilitychange'); document.hidden = false; }
    else elements.pump.emit(reason);
    elements.pump.emit('pointerup', { clientX: 204 });
    assert.equal(app.getState().strokes, 1);
    assert.equal(app.getState().pull, 0);
  }
  slide(elements);
  assert.equal(app.getState().cleared, 1);
});

